window.NCERT_CLOZE_DATA["Plant_Growth_and_Development"] = {"id": "Plant_Growth_and_Development", "title": "Plant Growth and Development", "subject": "Botany", "class": "Class 11", "chapter_no": 15, "stats": {"sentences": 268, "blanks": 223, "skipped_sentences": 101, "elements": 292}, "elements": [{"type": "h3", "content": "Chapter 15"}, {"type": "h1", "content": "Plant Growth and Development"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s1", "tokens": [{"t": "text", "v": "You have already studied the organisation of a flowering plant in Chapter 5."}], "blanks": [], "text": "You have already studied the organisation of a flowering plant in Chapter 5."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s2", "tokens": [{"t": "text", "v": "Have you ever thought about where and how the structures like roots, stems, leaves, flowers, fruits and seeds arise and that too in an orderly sequence?"}], "blanks": [], "text": "Have you ever thought about where and how the structures like roots, stems, leaves, flowers, fruits and seeds arise and that too in an orderly sequence?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s3", "tokens": [{"t": "text", "v": "You are, by now, aware of the terms seed, seedling, plantlet, mature plant."}], "blanks": [], "text": "You are, by now, aware of the terms seed, seedling, plantlet, mature plant."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s4", "tokens": [{"t": "text", "v": "You have also seen that trees continue to increase in height or girth over a period of time."}], "blanks": [], "text": "You have also seen that trees continue to increase in height or girth over a period of time."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s5", "tokens": [{"t": "text", "v": "However, the leaves, flowers and fruits of the same tree not only have limited dimensions but also appear and fall periodically and some time repeatedly."}], "blanks": [], "text": "However, the leaves, flowers and fruits of the same tree not only have limited dimensions but also appear and fall periodically and some time repeatedly."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s6", "tokens": [{"t": "text", "v": "Why does "}, {"t": "cloze", "v": "vegetative phase"}, {"t": "text", "v": " precede "}, {"t": "cloze", "v": "flowering"}, {"t": "text", "v": " in a plant?"}], "blanks": ["vegetative phase", "flowering"], "text": "Why does vegetative phase precede flowering in a plant?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s7", "tokens": [{"t": "text", "v": "All plant organs are made up of a variety of tissues; is there any relationship between the structure of a cell, a tissue, an organ and the function they perform?"}], "blanks": [], "text": "All plant organs are made up of a variety of tissues; is there any relationship between the structure of a cell, a tissue, an organ and the function they perform?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s8", "tokens": [{"t": "text", "v": "Can the structure and the function of these be altered?"}], "blanks": [], "text": "Can the structure and the function of these be altered?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s9", "tokens": [{"t": "text", "v": "All cells of a plant are descendents of the "}, {"t": "cloze", "v": "zygote"}, {"t": "text", "v": "."}], "blanks": ["zygote"], "text": "All cells of a plant are descendents of the zygote."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s10", "tokens": [{"t": "text", "v": "The question is, then, why and how do they have different structural and functional attributes?"}], "blanks": [], "text": "The question is, then, why and how do they have different structural and functional attributes?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s11", "tokens": [{"t": "text", "v": "Development is the sum of two processes: "}, {"t": "cloze", "v": "growth"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "differentiation"}, {"t": "text", "v": "."}], "blanks": ["growth", "differentiation"], "text": "Development is the sum of two processes: growth and differentiation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s12", "tokens": [{"t": "text", "v": "To begin with, it is essential and sufficient to know that the development of a mature plant from a "}, {"t": "cloze", "v": "zygote"}, {"t": "text", "v": " (fertilised egg) follow a precise and highly ordered succession of events."}], "blanks": ["zygote"], "text": "To begin with, it is essential and sufficient to know that the development of a mature plant from a zygote (fertilised egg) follow a precise and highly ordered succession of events."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s13", "tokens": [{"t": "text", "v": "During this process a complex body organisation is formed that produces roots, leaves, branches, flowers, fruits, and seeds, and eventually they die (Figure 15.1)."}], "blanks": [], "text": "During this process a complex body organisation is formed that produces roots, leaves, branches, flowers, fruits, and seeds, and eventually they die (Figure 15.1)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s14", "tokens": [{"t": "text", "v": "The first step in the process of plant growth is "}, {"t": "cloze", "v": "seed germination"}, {"t": "text", "v": "."}], "blanks": ["seed germination"], "text": "The first step in the process of plant growth is seed germination."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s15", "tokens": [{"t": "text", "v": "The seed germinates when favourable conditions for growth exist in the environment."}], "blanks": [], "text": "The seed germinates when favourable conditions for growth exist in the environment."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s16", "tokens": [{"t": "text", "v": "In absence of such favourable conditions the seeds do not germinate and goes into a period of "}, {"t": "cloze", "v": "suspended growth"}, {"t": "text", "v": " or rest."}], "blanks": ["suspended growth"], "text": "In absence of such favourable conditions the seeds do not germinate and goes into a period of suspended growth or rest."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s17", "tokens": [{"t": "text", "v": "Once favourable conditions return, the seeds resume "}, {"t": "cloze", "v": "metabolic activities"}, {"t": "text", "v": " and growth takes place."}], "blanks": ["metabolic activities"], "text": "Once favourable conditions return, the seeds resume metabolic activities and growth takes place."}, {"type": "h4", "content": "15.1 Growth"}, {"type": "h4", "content": "15.2 Differentiation, Dedifferentiation and Redifferentiation"}, {"type": "h4", "content": "15.3 Development"}, {"type": "h4", "content": "15.4 Plant Growth Regulators"}, {"type": "h4", "content": "15.5 Photoperiodism"}, {"type": "h4", "content": "15.6 Vernalisation"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s18", "tokens": [{"t": "text", "v": "In this chapter, you shall also study some of the factors which govern and control these developmental processes."}], "blanks": [], "text": "In this chapter, you shall also study some of the factors which govern and control these developmental processes."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s19", "tokens": [{"t": "text", "v": "These factors are both "}, {"t": "cloze", "v": "intrinsic"}, {"t": "text", "v": " (internal) and "}, {"t": "cloze", "v": "extrinsic"}, {"t": "text", "v": " (external) to the plant."}], "blanks": ["intrinsic", "extrinsic"], "text": "These factors are both intrinsic (internal) and extrinsic (external) to the plant."}, {"type": "h4", "content": "15.1 Growth"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s20", "tokens": [{"t": "text", "v": "Growth is regarded as one of the most fundamental and conspicuous characteristics of a living being."}], "blanks": [], "text": "Growth is regarded as one of the most fundamental and conspicuous characteristics of a living being."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s21", "tokens": [{"t": "text", "v": "What is growth?"}], "blanks": [], "text": "What is growth?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s22", "tokens": [{"t": "text", "v": "Growth can be defined as an "}, {"t": "cloze", "v": "irreversible permanent increase"}, {"t": "text", "v": " in size of an organ or its parts or even of an individual cell."}], "blanks": ["irreversible permanent increase"], "text": "Growth can be defined as an irreversible permanent increase in size of an organ or its parts or even of an individual cell."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s23", "tokens": [{"t": "text", "v": "Generally, growth is accompanied by "}, {"t": "cloze", "v": "metabolic processes"}, {"t": "text", "v": " (both "}, {"t": "cloze", "v": "anabolic and catabolic"}, {"t": "text", "v": "), that occur at the expense of energy."}], "blanks": ["metabolic processes", "anabolic and catabolic"], "text": "Generally, growth is accompanied by metabolic processes (both anabolic and catabolic), that occur at the expense of energy."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s24", "tokens": [{"t": "text", "v": "Therefore, for example, expansion of a leaf is growth."}], "blanks": [], "text": "Therefore, for example, expansion of a leaf is growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s25", "tokens": [{"t": "text", "v": "How would you describe the swelling of piece of wood when placed in water?"}], "blanks": [], "text": "How would you describe the swelling of piece of wood when placed in water?"}, {"type": "caption", "content": "Figure 15.1 Germination and seedling development in bean"}, {"type": "h4", "content": "15.1.1 Plant Growth Generally is Indeterminate"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s26", "tokens": [{"t": "text", "v": "Plant growth is unique because plants retain the capacity for "}, {"t": "cloze", "v": "unlimited growth"}, {"t": "text", "v": " throughout their life."}], "blanks": ["unlimited growth"], "text": "Plant growth is unique because plants retain the capacity for unlimited growth throughout their life."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s27", "tokens": [{"t": "text", "v": "This ability of the plants is due to the presence of "}, {"t": "cloze", "v": "meristems"}, {"t": "text", "v": " at certain locations in their body."}], "blanks": ["meristems"], "text": "This ability of the plants is due to the presence of meristems at certain locations in their body."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s28", "tokens": [{"t": "text", "v": "The cells of such meristems have the capacity to divide and self-perpetuate."}], "blanks": [], "text": "The cells of such meristems have the capacity to divide and self-perpetuate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s29", "tokens": [{"t": "text", "v": "The product, however, soon loses the capacity to divide and such cells make up the plant body."}], "blanks": [], "text": "The product, however, soon loses the capacity to divide and such cells make up the plant body."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s30", "tokens": [{"t": "text", "v": "This form of growth wherein new cells are always being added to the plant body by the activity of the meristem is called the "}, {"t": "cloze", "v": "open form of growth"}, {"t": "text", "v": "."}], "blanks": ["open form of growth"], "text": "This form of growth wherein new cells are always being added to the plant body by the activity of the meristem is called the open form of growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s31", "tokens": [{"t": "text", "v": "What would happen if the meristem ceases to divide?"}], "blanks": [], "text": "What would happen if the meristem ceases to divide?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s32", "tokens": [{"t": "text", "v": "Does this ever happen?"}], "blanks": [], "text": "Does this ever happen?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s33", "tokens": [{"t": "text", "v": "In Chapter 6, you have studied about the "}, {"t": "cloze", "v": "root apical meristem"}, {"t": "text", "v": " and the "}, {"t": "cloze", "v": "shoot apical meristem"}, {"t": "text", "v": "."}], "blanks": ["root apical meristem", "shoot apical meristem"], "text": "In Chapter 6, you have studied about the root apical meristem and the shoot apical meristem."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s34", "tokens": [{"t": "text", "v": "You know that they are responsible for the "}, {"t": "cloze", "v": "primary growth"}, {"t": "text", "v": " of the plants and principally contribute to the elongation of the plants along their axis."}], "blanks": ["primary growth"], "text": "You know that they are responsible for the primary growth of the plants and principally contribute to the elongation of the plants along their axis."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s35", "tokens": [{"t": "text", "v": "You also know that in dicotyledonous plants and gymnosperms, the "}, {"t": "cloze", "v": "lateral meristems"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "vascular cambium"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "cork-cambium"}, {"t": "text", "v": " appear later in life."}], "blanks": ["lateral meristems", "vascular cambium", "cork-cambium"], "text": "You also know that in dicotyledonous plants and gymnosperms, the lateral meristems, vascular cambium and cork-cambium appear later in life."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s36", "tokens": [{"t": "text", "v": "These are the meristems that cause the increase in the "}, {"t": "cloze", "v": "girth"}, {"t": "text", "v": " of the organs in which they are active."}], "blanks": ["girth"], "text": "These are the meristems that cause the increase in the girth of the organs in which they are active."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s37", "tokens": [{"t": "text", "v": "This is known as "}, {"t": "cloze", "v": "secondary growth"}, {"t": "text", "v": " of the plant (see Figure 15.2)."}], "blanks": ["secondary growth"], "text": "This is known as secondary growth of the plant (see Figure 15.2)."}, {"type": "h4", "content": "15.1.2 Growth is Measurable"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s38", "tokens": [{"t": "text", "v": "Growth, at a cellular level, is principally a consequence of increase in the amount of "}, {"t": "cloze", "v": "protoplasm"}, {"t": "text", "v": "."}], "blanks": ["protoplasm"], "text": "Growth, at a cellular level, is principally a consequence of increase in the amount of protoplasm."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s39", "tokens": [{"t": "text", "v": "Since increase in protoplasm is difficult to measure directly, one generally measures some quantity which is more or less proportional to it."}], "blanks": [], "text": "Since increase in protoplasm is difficult to measure directly, one generally measures some quantity which is more or less proportional to it."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s40", "tokens": [{"t": "text", "v": "Growth is, therefore, measured by a variety of parameters some of which are: increase in "}, {"t": "cloze", "v": "fresh weight"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "dry weight"}, {"t": "text", "v": ", length, area, volume and cell number."}], "blanks": ["fresh weight", "dry weight"], "text": "Growth is, therefore, measured by a variety of parameters some of which are: increase in fresh weight, dry weight, length, area, volume and cell number."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s41", "tokens": [{"t": "text", "v": "You may find it amazing to know that one single maize root apical mersitem can give rise to more than "}, {"t": "cloze", "v": "17,500"}, {"t": "text", "v": " new cells per hour, whereas cells in a watermelon may increase in size by upto "}, {"t": "cloze", "v": "3,50,000"}, {"t": "text", "v": " times."}], "blanks": ["17,500", "3,50,000"], "text": "You may find it amazing to know that one single maize root apical mersitem can give rise to more than 17,500 new cells per hour, whereas cells in a watermelon may increase in size by upto 3,50,000 times."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s42", "tokens": [{"t": "text", "v": "In the former, growth is expressed as increase in cell number; the latter expresses growth as increase in size of the cell."}], "blanks": [], "text": "In the former, growth is expressed as increase in cell number; the latter expresses growth as increase in size of the cell."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s43", "tokens": [{"t": "text", "v": "While the growth of a "}, {"t": "cloze", "v": "pollen tube"}, {"t": "text", "v": " is measured in terms of its length, an increase in surface area denotes the growth in a dorsiventral leaf."}], "blanks": ["pollen tube"], "text": "While the growth of a pollen tube is measured in terms of its length, an increase in surface area denotes the growth in a dorsiventral leaf."}, {"type": "h4", "content": "15.1.3 Phases of Growth"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s44", "tokens": [{"t": "text", "v": "The period of growth is generally divided into three phases, namely, "}, {"t": "cloze", "v": "meristematic"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "elongation"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "maturation"}, {"t": "text", "v": " (Figure 15.3)."}], "blanks": ["meristematic", "elongation", "maturation"], "text": "The period of growth is generally divided into three phases, namely, meristematic, elongation and maturation (Figure 15.3)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s45", "tokens": [{"t": "text", "v": "Let us understand this by looking at the root tips."}], "blanks": [], "text": "Let us understand this by looking at the root tips."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s46", "tokens": [{"t": "text", "v": "The constantly dividing cells, both at the root apex and the shoot apex, represent the "}, {"t": "cloze", "v": "meristematic phase"}, {"t": "text", "v": " of growth."}], "blanks": ["meristematic phase"], "text": "The constantly dividing cells, both at the root apex and the shoot apex, represent the meristematic phase of growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s47", "tokens": [{"t": "text", "v": "The cells in this region are rich in "}, {"t": "cloze", "v": "protoplasm"}, {"t": "text", "v": ", possess large conspicuous nuclei."}], "blanks": ["protoplasm"], "text": "The cells in this region are rich in protoplasm, possess large conspicuous nuclei."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s48", "tokens": [{"t": "text", "v": "Their cell walls are primary in nature, thin and "}, {"t": "cloze", "v": "cellulosic"}, {"t": "text", "v": " with abundant "}, {"t": "cloze", "v": "plasmodesmatal connections"}, {"t": "text", "v": "."}], "blanks": ["cellulosic", "plasmodesmatal connections"], "text": "Their cell walls are primary in nature, thin and cellulosic with abundant plasmodesmatal connections."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s49", "tokens": [{"t": "text", "v": "The cells proximal (just next, away from the tip) to the meristematic zone represent the "}, {"t": "cloze", "v": "phase of elongation"}, {"t": "text", "v": "."}], "blanks": ["phase of elongation"], "text": "The cells proximal (just next, away from the tip) to the meristematic zone represent the phase of elongation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s50", "tokens": [{"t": "cloze", "v": "Increased vacuolation"}, {"t": "text", "v": ", cell enlargement and new cell wall deposition are the characteristics of the cells in this phase."}], "blanks": ["Increased vacuolation"], "text": "Increased vacuolation, cell enlargement and new cell wall deposition are the characteristics of the cells in this phase."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s51", "tokens": [{"t": "text", "v": "Further away from the apex, i.e., more proximal to the "}, {"t": "cloze", "v": "phase of elongation"}, {"t": "text", "v": ", lies the portion of axis which is undergoing the "}, {"t": "cloze", "v": "phase of maturation"}, {"t": "text", "v": "."}], "blanks": ["phase of elongation", "phase of maturation"], "text": "Further away from the apex, i.e., more proximal to the phase of elongation, lies the portion of axis which is undergoing the phase of maturation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s52", "tokens": [{"t": "text", "v": "The cells of this zone, attain their maximal size in terms of wall thickening and protoplasmic modifications."}], "blanks": [], "text": "The cells of this zone, attain their maximal size in terms of wall thickening and protoplasmic modifications."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s53", "tokens": [{"t": "text", "v": "Most of the tissues and cell types you have studied in Chapter 6 represent this phase."}], "blanks": [], "text": "Most of the tissues and cell types you have studied in Chapter 6 represent this phase."}, {"type": "h4", "content": "15.1.4 Growth Rates"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s54", "tokens": [{"t": "text", "v": "The increased growth per unit time is termed as "}, {"t": "cloze", "v": "growth rate"}, {"t": "text", "v": "."}], "blanks": ["growth rate"], "text": "The increased growth per unit time is termed as growth rate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s55", "tokens": [{"t": "text", "v": "Thus, rate of growth can be expressed mathematically."}], "blanks": [], "text": "Thus, rate of growth can be expressed mathematically."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s56", "tokens": [{"t": "text", "v": "An organism, or a part of the organism can produce more cells in a variety of ways."}], "blanks": [], "text": "An organism, or a part of the organism can produce more cells in a variety of ways."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s57", "tokens": [{"t": "text", "v": "Figure15.4 Diagrammatic representation of : (a) Arithmetic (b) Geometric growth and (c) Stages during embryo development showing geometric and arithematic phases"}], "blanks": [], "text": "Figure15.4 Diagrammatic representation of : (a) Arithmetic (b) Geometric growth and (c) Stages during embryo development showing geometric and arithematic phases"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s58", "tokens": [{"t": "text", "v": "The growth rate shows an increase that may be "}, {"t": "cloze", "v": "arithmetic"}, {"t": "text", "v": " or "}, {"t": "cloze", "v": "geometrical"}, {"t": "text", "v": " (Figure 15.4)."}], "blanks": ["arithmetic", "geometrical"], "text": "The growth rate shows an increase that may be arithmetic or geometrical (Figure 15.4)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s59", "tokens": [{"t": "text", "v": "In "}, {"t": "cloze", "v": "arithmetic growth"}, {"t": "text", "v": ", following "}, {"t": "cloze", "v": "mitotic cell division"}, {"t": "text", "v": ", only one daughter cell continues to divide while the other differentiates and matures."}], "blanks": ["arithmetic growth", "mitotic cell division"], "text": "In arithmetic growth, following mitotic cell division, only one daughter cell continues to divide while the other differentiates and matures."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s60", "tokens": [{"t": "text", "v": "The simplest expression of "}, {"t": "cloze", "v": "arithmetic growth"}, {"t": "text", "v": " is exemplified by a root elongating at a constant rate."}], "blanks": ["arithmetic growth"], "text": "The simplest expression of arithmetic growth is exemplified by a root elongating at a constant rate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s61", "tokens": [{"t": "text", "v": "Look at Figure 15.5."}], "blanks": [], "text": "Look at Figure 15.5."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s62", "tokens": [{"t": "text", "v": "On plotting the length of the organ against time, a "}, {"t": "cloze", "v": "linear curve"}, {"t": "text", "v": " is obtained."}], "blanks": ["linear curve"], "text": "On plotting the length of the organ against time, a linear curve is obtained."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s63", "tokens": [{"t": "text", "v": "Mathematically, it is expressed as"}], "blanks": [], "text": "Mathematically, it is expressed as"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s64", "tokens": [{"t": "cloze", "v": "L t = L 0 + rt"}], "blanks": ["L t = L 0 + rt"], "text": "L t = L 0 + rt"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s65", "tokens": [{"t": "text", "v": "L t = length at time ‘t’"}], "blanks": [], "text": "L t = length at time ‘t’"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s66", "tokens": [{"t": "text", "v": "L 0 = length at time ‘zero’"}], "blanks": [], "text": "L 0 = length at time ‘zero’"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s67", "tokens": [{"t": "text", "v": "r = "}, {"t": "cloze", "v": "growth rate"}, {"t": "text", "v": " / elongation per unit time."}], "blanks": ["growth rate"], "text": "r = growth rate / elongation per unit time."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s68", "tokens": [{"t": "text", "v": "Let us now see what happens in geometrical growth."}], "blanks": [], "text": "Let us now see what happens in geometrical growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s69", "tokens": [{"t": "text", "v": "In most systems, the initial growth is slow ("}, {"t": "cloze", "v": "lag phase"}, {"t": "text", "v": "), and it increases rapidly thereafter – at an exponential rate (log or "}, {"t": "cloze", "v": "exponential phase"}, {"t": "text", "v": ")."}], "blanks": ["lag phase", "exponential phase"], "text": "In most systems, the initial growth is slow (lag phase), and it increases rapidly thereafter – at an exponential rate (log or exponential phase)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s70", "tokens": [{"t": "text", "v": "Here, both the progeny cells following "}, {"t": "cloze", "v": "mitotic cell division"}, {"t": "text", "v": " retain the ability to divide and continue to do so."}], "blanks": ["mitotic cell division"], "text": "Here, both the progeny cells following mitotic cell division retain the ability to divide and continue to do so."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s71", "tokens": [{"t": "text", "v": "However, with limited nutrient supply, the growth slows down leading to a "}, {"t": "cloze", "v": "stationary phase"}, {"t": "text", "v": "."}], "blanks": ["stationary phase"], "text": "However, with limited nutrient supply, the growth slows down leading to a stationary phase."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s72", "tokens": [{"t": "text", "v": "If we plot the parameter of growth against time, we get a typical "}, {"t": "cloze", "v": "sigmoid or S-curve"}, {"t": "text", "v": " (Figure 15.6)."}], "blanks": ["sigmoid or S-curve"], "text": "If we plot the parameter of growth against time, we get a typical sigmoid or S-curve (Figure 15.6)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s73", "tokens": [{"t": "text", "v": "A "}, {"t": "cloze", "v": "sigmoid curve"}, {"t": "text", "v": " is a characteristic of living organism growing in a natural environment."}], "blanks": ["sigmoid curve"], "text": "A sigmoid curve is a characteristic of living organism growing in a natural environment."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s74", "tokens": [{"t": "text", "v": "It is typical for all cells, tissues and organs of a plant."}], "blanks": [], "text": "It is typical for all cells, tissues and organs of a plant."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s75", "tokens": [{"t": "text", "v": "Can you think of more similar examples?"}], "blanks": [], "text": "Can you think of more similar examples?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s76", "tokens": [{"t": "text", "v": "What kind of a curve can you expect in a tree showing seasonal activities?"}], "blanks": [], "text": "What kind of a curve can you expect in a tree showing seasonal activities?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s77", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "exponential growth"}, {"t": "text", "v": " can be expressed as"}], "blanks": ["exponential growth"], "text": "The exponential growth can be expressed as"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s78", "tokens": [{"t": "cloze", "v": "W 1 = W 0 e rt"}], "blanks": ["W 1 = W 0 e rt"], "text": "W 1 = W 0 e rt"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s79", "tokens": [{"t": "cloze", "v": "W 1 = final size"}, {"t": "text", "v": " (weight, height, number etc.)"}], "blanks": ["W 1 = final size"], "text": "W 1 = final size (weight, height, number etc.)"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s80", "tokens": [{"t": "cloze", "v": "W 0 = initial size"}, {"t": "text", "v": " at the beginning of the period"}], "blanks": ["W 0 = initial size"], "text": "W 0 = initial size at the beginning of the period"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s81", "tokens": [{"t": "cloze", "v": "r = growth rate"}], "blanks": ["r = growth rate"], "text": "r = growth rate"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s82", "tokens": [{"t": "cloze", "v": "t = time of growth"}], "blanks": ["t = time of growth"], "text": "t = time of growth"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s83", "tokens": [{"t": "cloze", "v": "e = base of natural logarithms"}], "blanks": ["e = base of natural logarithms"], "text": "e = base of natural logarithms"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s84", "tokens": [{"t": "text", "v": "Here, r is the "}, {"t": "cloze", "v": "relative growth rate"}, {"t": "text", "v": " and is also the measure of the ability of the plant to produce new plant material, referred to as "}, {"t": "cloze", "v": "efficiency index"}, {"t": "text", "v": "."}], "blanks": ["relative growth rate", "efficiency index"], "text": "Here, r is the relative growth rate and is also the measure of the ability of the plant to produce new plant material, referred to as efficiency index."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s85", "tokens": [{"t": "text", "v": "Hence, the final size of W 1 depends on the initial size, W 0 ."}], "blanks": [], "text": "Hence, the final size of W 1 depends on the initial size, W 0 ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s86", "tokens": [{"t": "text", "v": "Quantitative comparisons between the growth of living system can also be made in two ways : (i) measurement and the comparison of total growth per unit time is called the "}, {"t": "cloze", "v": "absolute growth rate"}, {"t": "text", "v": "."}], "blanks": ["absolute growth rate"], "text": "Quantitative comparisons between the growth of living system can also be made in two ways : (i) measurement and the comparison of total growth per unit time is called the absolute growth rate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s87", "tokens": [{"t": "text", "v": "(ii) The growth of the given system per unit time expressed on a common basis, e.g., per unit initial parameter is called the "}, {"t": "cloze", "v": "relative growth rate"}, {"t": "text", "v": "."}], "blanks": ["relative growth rate"], "text": "(ii) The growth of the given system per unit time expressed on a common basis, e.g., per unit initial parameter is called the relative growth rate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s88", "tokens": [{"t": "text", "v": "In Figure 15.7 two leaves, A and B, are drawn that are of different sizes but shows absolute increase in area in the given time to give leaves, A 1 and B 1 ."}], "blanks": [], "text": "In Figure 15.7 two leaves, A and B, are drawn that are of different sizes but shows absolute increase in area in the given time to give leaves, A 1 and B 1 ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s89", "tokens": [{"t": "text", "v": "However, one of them shows much higher "}, {"t": "cloze", "v": "relative growth rate"}, {"t": "text", "v": "."}], "blanks": ["relative growth rate"], "text": "However, one of them shows much higher relative growth rate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s90", "tokens": [{"t": "text", "v": "Which one and why?"}], "blanks": [], "text": "Which one and why?"}, {"type": "h4", "content": "15.1.5 Conditions for Growth"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s91", "tokens": [{"t": "text", "v": "Why do you not try to write down what you think are necessary conditions for growth?"}], "blanks": [], "text": "Why do you not try to write down what you think are necessary conditions for growth?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s92", "tokens": [{"t": "text", "v": "This list may have water, oxygen and nutrients as very essential elements for growth."}], "blanks": [], "text": "This list may have water, oxygen and nutrients as very essential elements for growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s93", "tokens": [{"t": "text", "v": "The plant cells grow in size by "}, {"t": "cloze", "v": "cell enlargement"}, {"t": "text", "v": " which in turn requires "}, {"t": "cloze", "v": "water"}, {"t": "text", "v": "."}], "blanks": ["cell enlargement", "water"], "text": "The plant cells grow in size by cell enlargement which in turn requires water."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s94", "tokens": [{"t": "cloze", "v": "Turgidity of cells"}, {"t": "text", "v": " helps in "}, {"t": "cloze", "v": "extension growth"}, {"t": "text", "v": "."}], "blanks": ["Turgidity of cells", "extension growth"], "text": "Turgidity of cells helps in extension growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s95", "tokens": [{"t": "text", "v": "Thus, plant growth and further development is intimately linked to the water status of the plant."}], "blanks": [], "text": "Thus, plant growth and further development is intimately linked to the water status of the plant."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s96", "tokens": [{"t": "text", "v": "Water also provides the medium for "}, {"t": "cloze", "v": "enzymatic activities"}, {"t": "text", "v": " needed for growth."}], "blanks": ["enzymatic activities"], "text": "Water also provides the medium for enzymatic activities needed for growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s97", "tokens": [{"t": "text", "v": "Oxygen helps in releasing "}, {"t": "cloze", "v": "metabolic energy"}, {"t": "text", "v": " essential for growth activities."}], "blanks": ["metabolic energy"], "text": "Oxygen helps in releasing metabolic energy essential for growth activities."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s98", "tokens": [{"t": "text", "v": "Nutrients ("}, {"t": "cloze", "v": "macro and micro essential elements"}, {"t": "text", "v": ") are required by plants for the synthesis of "}, {"t": "cloze", "v": "protoplasm"}, {"t": "text", "v": " and act as source of energy."}], "blanks": ["macro and micro essential elements", "protoplasm"], "text": "Nutrients (macro and micro essential elements) are required by plants for the synthesis of protoplasm and act as source of energy."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s99", "tokens": [{"t": "text", "v": "In addition, every plant organism has an "}, {"t": "cloze", "v": "optimum temperature range"}, {"t": "text", "v": " best suited for its growth."}], "blanks": ["optimum temperature range"], "text": "In addition, every plant organism has an optimum temperature range best suited for its growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s100", "tokens": [{"t": "text", "v": "Any deviation from this range could be detrimental to its survival. Environmental signals such as "}, {"t": "cloze", "v": "light and gravity"}, {"t": "text", "v": " also affect certain phases/stages of growth."}], "blanks": ["light and gravity"], "text": "Any deviation from this range could be detrimental to its survival. Environmental signals such as light and gravity also affect certain phases/stages of growth."}, {"type": "h4", "content": "15.2 Differentiation, Dedifferentiation and Redifferentiation"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s101", "tokens": [{"t": "text", "v": "The cells derived from "}, {"t": "cloze", "v": "root apical and shoot-apical meristems"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "cambium"}, {"t": "text", "v": " differentiate and mature to perform specific functions."}], "blanks": ["root apical and shoot-apical meristems", "cambium"], "text": "The cells derived from root apical and shoot-apical meristems and cambium differentiate and mature to perform specific functions."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s102", "tokens": [{"t": "text", "v": "This act leading to maturation is termed as "}, {"t": "cloze", "v": "differentiation"}, {"t": "text", "v": " ."}], "blanks": ["differentiation"], "text": "This act leading to maturation is termed as differentiation ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s103", "tokens": [{"t": "text", "v": "During differentiation, cells undergo few to major structural changes both in their cell walls and protoplasm."}], "blanks": [], "text": "During differentiation, cells undergo few to major structural changes both in their cell walls and protoplasm."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s104", "tokens": [{"t": "text", "v": "For example, to form a "}, {"t": "cloze", "v": "tracheary element"}, {"t": "text", "v": ", the cells would lose their protoplasm."}], "blanks": ["tracheary element"], "text": "For example, to form a tracheary element, the cells would lose their protoplasm."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s105", "tokens": [{"t": "text", "v": "They also develop a very strong, elastic, "}, {"t": "cloze", "v": "lignocellulosic secondary cell walls"}, {"t": "text", "v": ", to carry water to long distances even under extreme tension."}], "blanks": ["lignocellulosic secondary cell walls"], "text": "They also develop a very strong, elastic, lignocellulosic secondary cell walls, to carry water to long distances even under extreme tension."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s106", "tokens": [{"t": "text", "v": "Try to correlate the various anatomical features you encounter in plants to the functions they perform."}], "blanks": [], "text": "Try to correlate the various anatomical features you encounter in plants to the functions they perform."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s107", "tokens": [{"t": "text", "v": "Plants show another interesting phenomenon."}], "blanks": [], "text": "Plants show another interesting phenomenon."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s108", "tokens": [{"t": "text", "v": "The living differentiated cells, that by now have lost the capacity to divide can regain the capacity of division under certain conditions."}], "blanks": [], "text": "The living differentiated cells, that by now have lost the capacity to divide can regain the capacity of division under certain conditions."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s109", "tokens": [{"t": "text", "v": "This phenomenon is termed as "}, {"t": "cloze", "v": "dedifferentiation"}, {"t": "text", "v": " ."}], "blanks": ["dedifferentiation"], "text": "This phenomenon is termed as dedifferentiation ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s110", "tokens": [{"t": "text", "v": "For example, formation of meristems – "}, {"t": "cloze", "v": "interfascicular cambium"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "cork cambium"}, {"t": "text", "v": " from fully differentiated parenchyma cells."}], "blanks": ["interfascicular cambium", "cork cambium"], "text": "For example, formation of meristems – interfascicular cambium and cork cambium from fully differentiated parenchyma cells."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s111", "tokens": [{"t": "text", "v": "While doing so, such meristems/tissues are able to divide and produce cells that once again lose the capacity to divide but mature to perform specific functions, i.e., get "}, {"t": "cloze", "v": "redifferentiated"}, {"t": "text", "v": " ."}], "blanks": ["redifferentiated"], "text": "While doing so, such meristems/tissues are able to divide and produce cells that once again lose the capacity to divide but mature to perform specific functions, i.e., get redifferentiated ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s112", "tokens": [{"t": "text", "v": "List some of the tissues in a woody dicotyledenous plant that are the products of redifferentiation."}], "blanks": [], "text": "List some of the tissues in a woody dicotyledenous plant that are the products of redifferentiation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s113", "tokens": [{"t": "text", "v": "How would you describe a tumour?"}], "blanks": [], "text": "How would you describe a tumour?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s114", "tokens": [{"t": "text", "v": "What would you call the parenchyma cells that are made to divide under controlled laboratory conditions during plant tissue culture?"}], "blanks": [], "text": "What would you call the parenchyma cells that are made to divide under controlled laboratory conditions during plant tissue culture?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s115", "tokens": [{"t": "text", "v": "Recall, in Section 15.1.1, we have mentioned that the growth in plants is open, i.e., it can be indeterminate or determinate."}], "blanks": [], "text": "Recall, in Section 15.1.1, we have mentioned that the growth in plants is open, i.e., it can be indeterminate or determinate."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s116", "tokens": [{"t": "text", "v": "Now, we may say that even differentiation in plants is open, because cells/tissues arising out of the same meristem have different structures at maturity."}], "blanks": [], "text": "Now, we may say that even differentiation in plants is open, because cells/tissues arising out of the same meristem have different structures at maturity."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s117", "tokens": [{"t": "text", "v": "The final structure at maturity of a cell/tissue is also determined by the location of the cell within."}], "blanks": [], "text": "The final structure at maturity of a cell/tissue is also determined by the location of the cell within."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s118", "tokens": [{"t": "text", "v": "For example, cells positioned away from root apical meristems differentiate as "}, {"t": "cloze", "v": "root-cap cells"}, {"t": "text", "v": ", while those pushed to the periphery mature as "}, {"t": "cloze", "v": "epidermis"}, {"t": "text", "v": "."}], "blanks": ["root-cap cells", "epidermis"], "text": "For example, cells positioned away from root apical meristems differentiate as root-cap cells, while those pushed to the periphery mature as epidermis."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s119", "tokens": [{"t": "text", "v": "Can you add a few more examples of open differentiation correlating the position of a cell to its position in an organ?"}], "blanks": [], "text": "Can you add a few more examples of open differentiation correlating the position of a cell to its position in an organ?"}, {"type": "h4", "content": "15.3 Development"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s120", "tokens": [{"t": "text", "v": "Development is a term that includes all changes that an organism goes through during its life cycle from germination of the seed to "}, {"t": "cloze", "v": "senescence"}, {"t": "text", "v": "."}], "blanks": ["senescence"], "text": "Development is a term that includes all changes that an organism goes through during its life cycle from germination of the seed to senescence."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s121", "tokens": [{"t": "text", "v": "Diagrammatic representation of the sequence of processes which constitute the development of a cell of a higher plant is given in Figure 15.8."}], "blanks": [], "text": "Diagrammatic representation of the sequence of processes which constitute the development of a cell of a higher plant is given in Figure 15.8."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s122", "tokens": [{"t": "text", "v": "It is also applicable to tissues/organs."}], "blanks": [], "text": "It is also applicable to tissues/organs."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s123", "tokens": [{"t": "text", "v": "Plants follow different pathways in response to environment or phases of life to form different kinds of structures."}], "blanks": [], "text": "Plants follow different pathways in response to environment or phases of life to form different kinds of structures."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s124", "tokens": [{"t": "text", "v": "This ability is called "}, {"t": "cloze", "v": "plasticity"}, {"t": "text", "v": " , e.g., "}, {"t": "cloze", "v": "heterophylly"}, {"t": "text", "v": " in cotton, coriander and larkspur."}], "blanks": ["plasticity", "heterophylly"], "text": "This ability is called plasticity , e.g., heterophylly in cotton, coriander and larkspur."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s125", "tokens": [{"t": "text", "v": "In such plants, the leaves of the juvenile plant are different in shape from those in mature plants."}], "blanks": [], "text": "In such plants, the leaves of the juvenile plant are different in shape from those in mature plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s126", "tokens": [{"t": "text", "v": "On the other hand, difference in shapes of leaves produced in air and those produced in water in "}, {"t": "cloze", "v": "buttercup"}, {"t": "text", "v": " also represent the "}, {"t": "cloze", "v": "heterophyllous development"}, {"t": "text", "v": " due to environment (Figure 15.9)."}], "blanks": ["buttercup", "heterophyllous development"], "text": "On the other hand, difference in shapes of leaves produced in air and those produced in water in buttercup also represent the heterophyllous development due to environment (Figure 15.9)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s127", "tokens": [{"t": "text", "v": "This phenomenon of "}, {"t": "cloze", "v": "heterophylly"}, {"t": "text", "v": " is an example of "}, {"t": "cloze", "v": "plasticity"}, {"t": "text", "v": "."}], "blanks": ["heterophylly", "plasticity"], "text": "This phenomenon of heterophylly is an example of plasticity."}, {"type": "caption", "content": "Figure 15.9 Heterophylly in (a) larkspur and (b) buttercup"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s128", "tokens": [{"t": "text", "v": "Thus, growth, differentiation and development are very closely related events in the life of a plant."}], "blanks": [], "text": "Thus, growth, differentiation and development are very closely related events in the life of a plant."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s129", "tokens": [{"t": "text", "v": "Broadly, development is considered as the sum of "}, {"t": "cloze", "v": "growth and differentiation"}, {"t": "text", "v": "."}], "blanks": ["growth and differentiation"], "text": "Broadly, development is considered as the sum of growth and differentiation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s130", "tokens": [{"t": "text", "v": "Development in plants (i.e., both growth and differentiation) is under the control of "}, {"t": "cloze", "v": "intrinsic and extrinsic factors"}, {"t": "text", "v": "."}], "blanks": ["intrinsic and extrinsic factors"], "text": "Development in plants (i.e., both growth and differentiation) is under the control of intrinsic and extrinsic factors."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s131", "tokens": [{"t": "text", "v": "The former includes both intracellular (genetic) or intercellular factors (chemicals such as "}, {"t": "cloze", "v": "plant growth regulators"}, {"t": "text", "v": ") while the latter includes light, temperature, water, oxygen, nutrition, etc."}], "blanks": ["plant growth regulators"], "text": "The former includes both intracellular (genetic) or intercellular factors (chemicals such as plant growth regulators) while the latter includes light, temperature, water, oxygen, nutrition, etc."}, {"type": "h4", "content": "15.4 Plant Growth Regulators"}, {"type": "h4", "content": "15.4.1 Characteristics"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s132", "tokens": [{"t": "text", "v": "The plant growth regulators (PGRs) are small, simple molecules of diverse chemical composition."}], "blanks": [], "text": "The plant growth regulators (PGRs) are small, simple molecules of diverse chemical composition."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s133", "tokens": [{"t": "text", "v": "They could be indole compounds ("}, {"t": "cloze", "v": "indole-3-acetic acid, IAA"}, {"t": "text", "v": "); adenine derivatives (N 6 -furfurylamino purine, kinetin), derivatives of carotenoids (abscisic acid, ABA); terpenes ("}, {"t": "cloze", "v": "gibberellic acid, GA 3"}, {"t": "text", "v": " ) or gases (ethylene, C 2 H 4 )."}], "blanks": ["indole-3-acetic acid, IAA", "gibberellic acid, GA 3"], "text": "They could be indole compounds (indole-3-acetic acid, IAA); adenine derivatives (N 6 -furfurylamino purine, kinetin), derivatives of carotenoids (abscisic acid, ABA); terpenes (gibberellic acid, GA 3 ) or gases (ethylene, C 2 H 4 )."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s134", "tokens": [{"t": "text", "v": "Plant growth regulators are variously described as plant growth substances, plant hormones or "}, {"t": "cloze", "v": "phytohormones"}, {"t": "text", "v": " in literature."}], "blanks": ["phytohormones"], "text": "Plant growth regulators are variously described as plant growth substances, plant hormones or phytohormones in literature."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s135", "tokens": [{"t": "text", "v": "The PGRs can be broadly divided into two groups based on their functions in a living plant body."}], "blanks": [], "text": "The PGRs can be broadly divided into two groups based on their functions in a living plant body."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s136", "tokens": [{"t": "text", "v": "One group of PGRs are involved in growth promoting activities, such as cell division, cell enlargement, pattern formation, tropic growth, flowering, fruiting and seed formation."}], "blanks": [], "text": "One group of PGRs are involved in growth promoting activities, such as cell division, cell enlargement, pattern formation, tropic growth, flowering, fruiting and seed formation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s137", "tokens": [{"t": "text", "v": "These are also called plant growth promoters, e.g., "}, {"t": "cloze", "v": "auxins, gibberellins and cytokinins"}, {"t": "text", "v": "."}], "blanks": ["auxins, gibberellins and cytokinins"], "text": "These are also called plant growth promoters, e.g., auxins, gibberellins and cytokinins."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s138", "tokens": [{"t": "text", "v": "The PGRs of the other group play an important role in plant responses to wounds and stresses of biotic and abiotic origin."}], "blanks": [], "text": "The PGRs of the other group play an important role in plant responses to wounds and stresses of biotic and abiotic origin."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s139", "tokens": [{"t": "text", "v": "They are also involved in various growth inhibiting activities such as "}, {"t": "cloze", "v": "dormancy and abscission"}, {"t": "text", "v": "."}], "blanks": ["dormancy and abscission"], "text": "They are also involved in various growth inhibiting activities such as dormancy and abscission."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s140", "tokens": [{"t": "text", "v": "The PGR "}, {"t": "cloze", "v": "abscisic acid"}, {"t": "text", "v": " belongs to this group. The gaseous PGR, "}, {"t": "cloze", "v": "ethylene"}, {"t": "text", "v": ", could fit either of the groups, but it is largely an inhibitor of growth activities."}], "blanks": ["abscisic acid", "ethylene"], "text": "The PGR abscisic acid belongs to this group. The gaseous PGR, ethylene, could fit either of the groups, but it is largely an inhibitor of growth activities."}, {"type": "h4", "content": "15.4.2 The Discovery of Plant Growth Regulators"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s141", "tokens": [{"t": "text", "v": "Interestingly, the discovery of each of the five major groups of PGRs have been accidental. All this started with the observation of "}, {"t": "cloze", "v": "Charles Darwin"}, {"t": "text", "v": " and his son Francis Darwin when they observed that the coleoptiles of "}, {"t": "cloze", "v": "canary grass"}, {"t": "text", "v": " responded to unilateral illumination by growing towards the light source (phototropism)."}], "blanks": ["Charles Darwin", "canary grass"], "text": "Interestingly, the discovery of each of the five major groups of PGRs have been accidental. All this started with the observation of Charles Darwin and his son Francis Darwin when they observed that the coleoptiles of canary grass responded to unilateral illumination by growing towards the light source (phototropism)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s142", "tokens": [{"t": "text", "v": "After a series of experiments, it was concluded that the "}, {"t": "cloze", "v": "tip of coleoptile"}, {"t": "text", "v": " was the site of transmittable influence that caused the bending of the entire coleoptile (Figure 15.10)."}], "blanks": ["tip of coleoptile"], "text": "After a series of experiments, it was concluded that the tip of coleoptile was the site of transmittable influence that caused the bending of the entire coleoptile (Figure 15.10)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s143", "tokens": [{"t": "cloze", "v": "Auxin"}, {"t": "text", "v": " was isolated by "}, {"t": "cloze", "v": "F.W."}], "blanks": ["Auxin", "F.W."], "text": "Auxin was isolated by F.W."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s144", "tokens": [{"t": "cloze", "v": "Went"}, {"t": "text", "v": " from tips of coleoptiles of "}, {"t": "cloze", "v": "oat"}, {"t": "text", "v": " seedlings."}], "blanks": ["Went", "oat"], "text": "Went from tips of coleoptiles of oat seedlings."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s145", "tokens": [{"t": "text", "v": "Figure 15.10 Experiment used to demonstrate that tip of the coleoptile is the source of "}, {"t": "cloze", "v": "auxin"}, {"t": "text", "v": "."}], "blanks": ["auxin"], "text": "Figure 15.10 Experiment used to demonstrate that tip of the coleoptile is the source of auxin."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s146", "tokens": [{"t": "text", "v": "Arrows indicate direction of light"}], "blanks": [], "text": "Arrows indicate direction of light"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s147", "tokens": [{"t": "text", "v": "The ‘"}, {"t": "cloze", "v": "bakanae"}, {"t": "text", "v": "’ (foolish seedling) disease of rice seedlings, was caused by a fungal pathogen "}, {"t": "cloze", "v": "Gibberella fujikuroi"}, {"t": "text", "v": " ."}], "blanks": ["bakanae", "Gibberella fujikuroi"], "text": "The ‘bakanae’ (foolish seedling) disease of rice seedlings, was caused by a fungal pathogen Gibberella fujikuroi ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s148", "tokens": [{"t": "text", "v": "E."}], "blanks": [], "text": "E."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s149", "tokens": [{"t": "cloze", "v": "Kurosawa"}, {"t": "text", "v": " ("}, {"t": "cloze", "v": "1926"}, {"t": "text", "v": ") reported the appearance of symptoms of the disease in rice seedlings when they were treated with sterile filtrates of the fungus."}], "blanks": ["Kurosawa", "1926"], "text": "Kurosawa (1926) reported the appearance of symptoms of the disease in rice seedlings when they were treated with sterile filtrates of the fungus."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s150", "tokens": [{"t": "text", "v": "The active substances were later identified as "}, {"t": "cloze", "v": "gibberellic acid"}, {"t": "text", "v": "."}], "blanks": ["gibberellic acid"], "text": "The active substances were later identified as gibberellic acid."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s151", "tokens": [{"t": "text", "v": "F."}], "blanks": [], "text": "F."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s152", "tokens": [{"t": "cloze", "v": "Skoog"}, {"t": "text", "v": " and his co-workers observed that from the internodal segments of tobacco stems the callus (a mass of undifferentiated cells) proliferated only if, in addition to auxins the nutrients medium was supplemented with one of the following: extracts of vascular tissues, yeast extract, coconut milk or DNA."}], "blanks": ["Skoog"], "text": "Skoog and his co-workers observed that from the internodal segments of tobacco stems the callus (a mass of undifferentiated cells) proliferated only if, in addition to auxins the nutrients medium was supplemented with one of the following: extracts of vascular tissues, yeast extract, coconut milk or DNA."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s153", "tokens": [{"t": "cloze", "v": "Miller et al. (1955)"}, {"t": "text", "v": ", later identified and crystallised the cytokinesis promoting active substance that they termed "}, {"t": "cloze", "v": "kinetin"}, {"t": "text", "v": "."}], "blanks": ["Miller et al. (1955)", "kinetin"], "text": "Miller et al. (1955), later identified and crystallised the cytokinesis promoting active substance that they termed kinetin."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s154", "tokens": [{"t": "text", "v": "During mid-1960s, three independent researches reported the purification and chemical characterisation of three different kinds of inhibitors: "}, {"t": "cloze", "v": "inhibitor-B"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "abscission II"}, {"t": "text", "v": " and dormin."}], "blanks": ["inhibitor-B", "abscission II"], "text": "During mid-1960s, three independent researches reported the purification and chemical characterisation of three different kinds of inhibitors: inhibitor-B, abscission II and dormin."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s155", "tokens": [{"t": "text", "v": "Later all the three were proved to be chemically identical. It was named "}, {"t": "cloze", "v": "abscisic acid (ABA)"}, {"t": "text", "v": "."}], "blanks": ["abscisic acid (ABA)"], "text": "Later all the three were proved to be chemically identical. It was named abscisic acid (ABA)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s156", "tokens": [{"t": "text", "v": "H.H."}], "blanks": [], "text": "H.H."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s157", "tokens": [{"t": "cloze", "v": "Cousins (1910)"}, {"t": "text", "v": " confirmed the release of a volatile substance from ripened oranges that hastened the ripening of stored unripened bananas."}], "blanks": ["Cousins (1910)"], "text": "Cousins (1910) confirmed the release of a volatile substance from ripened oranges that hastened the ripening of stored unripened bananas."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s158", "tokens": [{"t": "text", "v": "Later this volatile substance was identified as "}, {"t": "cloze", "v": "ethylene"}, {"t": "text", "v": ", a gaseous PGR."}], "blanks": ["ethylene"], "text": "Later this volatile substance was identified as ethylene, a gaseous PGR."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s159", "tokens": [{"t": "text", "v": "Let us study some of the physiological effects of these five categories of PGRs in the next section."}], "blanks": [], "text": "Let us study some of the physiological effects of these five categories of PGRs in the next section."}, {"type": "h4", "content": "15.4.3 Physiological Effects of Plant Growth Regulators"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s160", "tokens": [{"t": "text", "v": "15.4.3.1 Auxins"}], "blanks": [], "text": "15.4.3.1 Auxins"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s161", "tokens": [{"t": "text", "v": "Auxins (from Greek ‘"}, {"t": "cloze", "v": "auxein"}, {"t": "text", "v": "’ : to grow) was first isolated from "}, {"t": "cloze", "v": "human urine"}, {"t": "text", "v": "."}], "blanks": ["auxein", "human urine"], "text": "Auxins (from Greek ‘auxein’ : to grow) was first isolated from human urine."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s162", "tokens": [{"t": "text", "v": "The term ‘auxin’ is applied to the "}, {"t": "cloze", "v": "indole-3-acetic acid (IAA)"}, {"t": "text", "v": ", and to other natural and synthetic compounds having certain growth regulating properties."}], "blanks": ["indole-3-acetic acid (IAA)"], "text": "The term ‘auxin’ is applied to the indole-3-acetic acid (IAA), and to other natural and synthetic compounds having certain growth regulating properties."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s163", "tokens": [{"t": "text", "v": "They are generally produced by the growing apices of the stems and roots, from where they migrate to the regions of their action."}], "blanks": [], "text": "They are generally produced by the growing apices of the stems and roots, from where they migrate to the regions of their action."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s164", "tokens": [{"t": "text", "v": "Auxins like "}, {"t": "cloze", "v": "IAA"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "indole butyric acid (IBA)"}, {"t": "text", "v": " have been isolated from plants."}], "blanks": ["IAA", "indole butyric acid (IBA)"], "text": "Auxins like IAA and indole butyric acid (IBA) have been isolated from plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s165", "tokens": [{"t": "cloze", "v": "NAA"}, {"t": "text", "v": " (naphthalene acetic acid) and "}, {"t": "cloze", "v": "2, 4-D"}, {"t": "text", "v": " (2, 4-dichlorophenoxyacetic) are synthetic auxins."}], "blanks": ["NAA", "2, 4-D"], "text": "NAA (naphthalene acetic acid) and 2, 4-D (2, 4-dichlorophenoxyacetic) are synthetic auxins."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s166", "tokens": [{"t": "text", "v": "All these auxins have been used extensively in agricultural and horticultural practices."}], "blanks": [], "text": "All these auxins have been used extensively in agricultural and horticultural practices."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s167", "tokens": [{"t": "text", "v": "They help to initiate rooting in stem cuttings, an application widely used for plant propagation."}], "blanks": [], "text": "They help to initiate rooting in stem cuttings, an application widely used for plant propagation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s168", "tokens": [{"t": "text", "v": "Auxins promote flowering e.g. in "}, {"t": "cloze", "v": "pineapples"}, {"t": "text", "v": "."}], "blanks": ["pineapples"], "text": "Auxins promote flowering e.g. in pineapples."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s169", "tokens": [{"t": "text", "v": "They help to prevent fruit and leaf drop at early stages but promote the abscission of older mature leaves and fruits."}], "blanks": [], "text": "They help to prevent fruit and leaf drop at early stages but promote the abscission of older mature leaves and fruits."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s170", "tokens": [{"t": "text", "v": "In most higher plants, the growing apical bud inhibits the growth of the lateral (axillary) buds, a phenomenon called "}, {"t": "cloze", "v": "apical dominance"}, {"t": "text", "v": " ."}], "blanks": ["apical dominance"], "text": "In most higher plants, the growing apical bud inhibits the growth of the lateral (axillary) buds, a phenomenon called apical dominance ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s171", "tokens": [{"t": "text", "v": "Removal of shoot tips ("}, {"t": "cloze", "v": "decapitation"}, {"t": "text", "v": ") usually results in the growth of lateral buds (Figure 15.11)."}], "blanks": ["decapitation"], "text": "Removal of shoot tips (decapitation) usually results in the growth of lateral buds (Figure 15.11)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s172", "tokens": [{"t": "text", "v": "It is widely applied in tea plantations, hedge-making."}], "blanks": [], "text": "It is widely applied in tea plantations, hedge-making."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s173", "tokens": [{"t": "text", "v": "Can you explain why?"}], "blanks": [], "text": "Can you explain why?"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s174", "tokens": [{"t": "text", "v": "Figure 15.11 Apical dominance in plants :"}], "blanks": [], "text": "Figure 15.11 Apical dominance in plants :"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s175", "tokens": [{"t": "text", "v": "(a) A plant with apical bud intact"}], "blanks": [], "text": "(a) A plant with apical bud intact"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s176", "tokens": [{"t": "text", "v": "(b) A plant with "}, {"t": "cloze", "v": "apical bud"}, {"t": "text", "v": " removed"}], "blanks": ["apical bud"], "text": "(b) A plant with apical bud removed"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s177", "tokens": [{"t": "text", "v": "Note the growth of "}, {"t": "cloze", "v": "lateral buds"}, {"t": "text", "v": " into branches after "}, {"t": "cloze", "v": "decapitation"}, {"t": "text", "v": "."}], "blanks": ["lateral buds", "decapitation"], "text": "Note the growth of lateral buds into branches after decapitation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s178", "tokens": [{"t": "text", "v": "Auxins also induce "}, {"t": "cloze", "v": "parthenocarpy"}, {"t": "text", "v": ", e.g., in "}, {"t": "cloze", "v": "tomatoes"}, {"t": "text", "v": "."}], "blanks": ["parthenocarpy", "tomatoes"], "text": "Auxins also induce parthenocarpy, e.g., in tomatoes."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s179", "tokens": [{"t": "text", "v": "They are widely used as "}, {"t": "cloze", "v": "herbicides"}, {"t": "text", "v": "."}], "blanks": ["herbicides"], "text": "They are widely used as herbicides."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s180", "tokens": [{"t": "cloze", "v": "2, 4-D"}, {"t": "text", "v": ", widely used to kill "}, {"t": "cloze", "v": "dicotyledonous weeds"}, {"t": "text", "v": ", does not affect mature monocotyledonous plants."}], "blanks": ["2, 4-D", "dicotyledonous weeds"], "text": "2, 4-D, widely used to kill dicotyledonous weeds, does not affect mature monocotyledonous plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s181", "tokens": [{"t": "text", "v": "It is used to prepare weed-free lawns by gardeners."}], "blanks": [], "text": "It is used to prepare weed-free lawns by gardeners."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s182", "tokens": [{"t": "text", "v": "Auxin also controls "}, {"t": "cloze", "v": "xylem differentiation"}, {"t": "text", "v": " and helps in cell division."}], "blanks": ["xylem differentiation"], "text": "Auxin also controls xylem differentiation and helps in cell division."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s183", "tokens": [{"t": "text", "v": "15.4.3.2 "}, {"t": "cloze", "v": "Gibberellins"}], "blanks": ["Gibberellins"], "text": "15.4.3.2 Gibberellins"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s184", "tokens": [{"t": "text", "v": "Gibberellins are another kind of "}, {"t": "cloze", "v": "promotory PGR"}, {"t": "text", "v": "."}], "blanks": ["promotory PGR"], "text": "Gibberellins are another kind of promotory PGR."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s185", "tokens": [{"t": "text", "v": "There are "}, {"t": "cloze", "v": "more than 100 gibberellins"}, {"t": "text", "v": " reported from widely different organisms such as fungi and higher plants."}], "blanks": ["more than 100 gibberellins"], "text": "There are more than 100 gibberellins reported from widely different organisms such as fungi and higher plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s186", "tokens": [{"t": "text", "v": "They are denoted as "}, {"t": "cloze", "v": "GA 1"}, {"t": "text", "v": " , GA 2 , "}, {"t": "cloze", "v": "GA 3"}, {"t": "text", "v": " and so on."}], "blanks": ["GA 1", "GA 3"], "text": "They are denoted as GA 1 , GA 2 , GA 3 and so on."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s187", "tokens": [{"t": "text", "v": "However, "}, {"t": "cloze", "v": "Gibberellic acid"}, {"t": "text", "v": " ("}, {"t": "cloze", "v": "GA 3"}, {"t": "text", "v": " ) was one of the first gibberellins to be discovered and remains the most intensively studied form."}], "blanks": ["Gibberellic acid", "GA 3"], "text": "However, Gibberellic acid (GA 3 ) was one of the first gibberellins to be discovered and remains the most intensively studied form."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s188", "tokens": [{"t": "text", "v": "All GAs are "}, {"t": "cloze", "v": "acidic"}, {"t": "text", "v": ". They produce a wide range of physiological responses in the plants."}], "blanks": ["acidic"], "text": "All GAs are acidic. They produce a wide range of physiological responses in the plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s189", "tokens": [{"t": "text", "v": "Their ability to cause an increase in length of axis is used to increase the length of grapes stalks."}], "blanks": [], "text": "Their ability to cause an increase in length of axis is used to increase the length of grapes stalks."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s190", "tokens": [{"t": "text", "v": "Gibberellins, cause fruits like "}, {"t": "cloze", "v": "apple"}, {"t": "text", "v": " to elongate and improve its shape."}], "blanks": ["apple"], "text": "Gibberellins, cause fruits like apple to elongate and improve its shape."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s191", "tokens": [{"t": "text", "v": "They also delay "}, {"t": "cloze", "v": "senescence"}, {"t": "text", "v": "."}], "blanks": ["senescence"], "text": "They also delay senescence."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s192", "tokens": [{"t": "text", "v": "Thus, the fruits can be left on the tree longer so as to extend the market period."}], "blanks": [], "text": "Thus, the fruits can be left on the tree longer so as to extend the market period."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s193", "tokens": [{"t": "cloze", "v": "GA 3"}, {"t": "text", "v": " is used to speed up the "}, {"t": "cloze", "v": "malting process"}, {"t": "text", "v": " in brewing industry."}], "blanks": ["GA 3", "malting process"], "text": "GA 3 is used to speed up the malting process in brewing industry."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s194", "tokens": [{"t": "text", "v": "Sugarcane stores carbohydrate as sugar in their stems."}], "blanks": [], "text": "Sugarcane stores carbohydrate as sugar in their stems."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s195", "tokens": [{"t": "text", "v": "Spraying sugarcane crop with "}, {"t": "cloze", "v": "gibberellins"}, {"t": "text", "v": " increases the length of the stem, thus increasing the yield by as much as "}, {"t": "cloze", "v": "20 tonnes per acre"}, {"t": "text", "v": "."}], "blanks": ["gibberellins", "20 tonnes per acre"], "text": "Spraying sugarcane crop with gibberellins increases the length of the stem, thus increasing the yield by as much as 20 tonnes per acre."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s196", "tokens": [{"t": "text", "v": "Spraying juvenile "}, {"t": "cloze", "v": "conifers"}, {"t": "text", "v": " with "}, {"t": "cloze", "v": "GAs"}, {"t": "text", "v": " hastens the maturity period, thus leading to early seed production."}], "blanks": ["conifers", "GAs"], "text": "Spraying juvenile conifers with GAs hastens the maturity period, thus leading to early seed production."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s197", "tokens": [{"t": "text", "v": "Gibberellins also promotes "}, {"t": "cloze", "v": "bolting"}, {"t": "text", "v": " (internode elongation just prior to flowering) in beet, cabbages and many plants with "}, {"t": "cloze", "v": "rosette habit"}, {"t": "text", "v": "."}], "blanks": ["bolting", "rosette habit"], "text": "Gibberellins also promotes bolting (internode elongation just prior to flowering) in beet, cabbages and many plants with rosette habit."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s198", "tokens": [{"t": "text", "v": "15.4.3.3 "}, {"t": "cloze", "v": "Cytokinins"}], "blanks": ["Cytokinins"], "text": "15.4.3.3 Cytokinins"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s199", "tokens": [{"t": "text", "v": "Cytokinins have specific effects on "}, {"t": "cloze", "v": "cytokinesis"}, {"t": "text", "v": ", and were discovered as "}, {"t": "cloze", "v": "kinetin"}, {"t": "text", "v": " (a modified form of adenine, a purine) from the autoclaved herring sperm DNA."}], "blanks": ["cytokinesis", "kinetin"], "text": "Cytokinins have specific effects on cytokinesis, and were discovered as kinetin (a modified form of adenine, a purine) from the autoclaved herring sperm DNA."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s200", "tokens": [{"t": "cloze", "v": "Kinetin"}, {"t": "text", "v": " does not occur naturally in plants."}], "blanks": ["Kinetin"], "text": "Kinetin does not occur naturally in plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s201", "tokens": [{"t": "text", "v": "Search for natural substances with cytokinin-like activities led to the isolation of "}, {"t": "cloze", "v": "zeatin"}, {"t": "text", "v": " from "}, {"t": "cloze", "v": "corn-kernels and coconut milk"}, {"t": "text", "v": "."}], "blanks": ["zeatin", "corn-kernels and coconut milk"], "text": "Search for natural substances with cytokinin-like activities led to the isolation of zeatin from corn-kernels and coconut milk."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s202", "tokens": [{"t": "text", "v": "Since the discovery of "}, {"t": "cloze", "v": "zeatin"}, {"t": "text", "v": ", several naturally occurring cytokinins, and some synthetic compounds with cell division promoting activity, have been identified."}], "blanks": ["zeatin"], "text": "Since the discovery of zeatin, several naturally occurring cytokinins, and some synthetic compounds with cell division promoting activity, have been identified."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s203", "tokens": [{"t": "text", "v": "Natural cytokinins are synthesised in regions where rapid cell division occurs, for example, "}, {"t": "cloze", "v": "root apices"}, {"t": "text", "v": ", developing shoot buds, young fruits etc. It helps to produce new leaves, chloroplasts in leaves, lateral shoot growth and adventitious shoot formation."}], "blanks": ["root apices"], "text": "Natural cytokinins are synthesised in regions where rapid cell division occurs, for example, root apices, developing shoot buds, young fruits etc. It helps to produce new leaves, chloroplasts in leaves, lateral shoot growth and adventitious shoot formation."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s204", "tokens": [{"t": "text", "v": "Cytokinins help overcome the "}, {"t": "cloze", "v": "apical dominance"}, {"t": "text", "v": "."}], "blanks": ["apical dominance"], "text": "Cytokinins help overcome the apical dominance."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s205", "tokens": [{"t": "text", "v": "They promote "}, {"t": "cloze", "v": "nutrient mobilisation"}, {"t": "text", "v": " which helps in the "}, {"t": "cloze", "v": "delay of leaf senescence"}, {"t": "text", "v": "."}], "blanks": ["nutrient mobilisation", "delay of leaf senescence"], "text": "They promote nutrient mobilisation which helps in the delay of leaf senescence."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s206", "tokens": [{"t": "text", "v": "15.4.3.4 Ethylene"}], "blanks": [], "text": "15.4.3.4 Ethylene"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s207", "tokens": [{"t": "text", "v": "Ethylene is a simple "}, {"t": "cloze", "v": "gaseous PGR"}, {"t": "text", "v": "."}], "blanks": ["gaseous PGR"], "text": "Ethylene is a simple gaseous PGR."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s208", "tokens": [{"t": "text", "v": "It is synthesised in large amounts by tissues undergoing senescence and "}, {"t": "cloze", "v": "ripening fruits"}, {"t": "text", "v": "."}], "blanks": ["ripening fruits"], "text": "It is synthesised in large amounts by tissues undergoing senescence and ripening fruits."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s209", "tokens": [{"t": "text", "v": "Influences of ethylene on plants include horizontal growth of seedlings, swelling of the axis and "}, {"t": "cloze", "v": "apical hook formation"}, {"t": "text", "v": " in dicot seedlings."}], "blanks": ["apical hook formation"], "text": "Influences of ethylene on plants include horizontal growth of seedlings, swelling of the axis and apical hook formation in dicot seedlings."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s210", "tokens": [{"t": "text", "v": "Ethylene promotes senescence and "}, {"t": "cloze", "v": "abscission"}, {"t": "text", "v": " of plant organs especially of leaves and flowers."}], "blanks": ["abscission"], "text": "Ethylene promotes senescence and abscission of plant organs especially of leaves and flowers."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s211", "tokens": [{"t": "text", "v": "Ethylene is highly effective in "}, {"t": "cloze", "v": "fruit ripening"}, {"t": "text", "v": "."}], "blanks": ["fruit ripening"], "text": "Ethylene is highly effective in fruit ripening."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s212", "tokens": [{"t": "text", "v": "It enhances the "}, {"t": "cloze", "v": "respiration rate"}, {"t": "text", "v": " during ripening of the fruits."}], "blanks": ["respiration rate"], "text": "It enhances the respiration rate during ripening of the fruits."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s213", "tokens": [{"t": "text", "v": "This rise in rate of respiration is called "}, {"t": "cloze", "v": "respiratory climactic"}, {"t": "text", "v": "."}], "blanks": ["respiratory climactic"], "text": "This rise in rate of respiration is called respiratory climactic."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s214", "tokens": [{"t": "text", "v": "Ethylene breaks seed and bud "}, {"t": "cloze", "v": "dormancy"}, {"t": "text", "v": ", initiates germination in peanut seeds, sprouting of potato tubers."}], "blanks": ["dormancy"], "text": "Ethylene breaks seed and bud dormancy, initiates germination in peanut seeds, sprouting of potato tubers."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s215", "tokens": [{"t": "text", "v": "Ethylene promotes rapid "}, {"t": "cloze", "v": "internode/petiole elongation"}, {"t": "text", "v": " in "}, {"t": "cloze", "v": "deep water rice"}, {"t": "text", "v": " plants."}], "blanks": ["internode/petiole elongation", "deep water rice"], "text": "Ethylene promotes rapid internode/petiole elongation in deep water rice plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s216", "tokens": [{"t": "text", "v": "It helps leaves/upper parts of the shoot to remain above water."}], "blanks": [], "text": "It helps leaves/upper parts of the shoot to remain above water."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s217", "tokens": [{"t": "text", "v": "Ethylene also promotes root growth and "}, {"t": "cloze", "v": "root hair formation"}, {"t": "text", "v": ", thus helping the plants to increase their absorption surface."}], "blanks": ["root hair formation"], "text": "Ethylene also promotes root growth and root hair formation, thus helping the plants to increase their absorption surface."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s218", "tokens": [{"t": "text", "v": "Ethylene is used to initiate flowering and for synchronising fruit-set in "}, {"t": "cloze", "v": "pineapples"}, {"t": "text", "v": "."}], "blanks": ["pineapples"], "text": "Ethylene is used to initiate flowering and for synchronising fruit-set in pineapples."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s219", "tokens": [{"t": "text", "v": "It also induces flowering in "}, {"t": "cloze", "v": "mango"}, {"t": "text", "v": "."}], "blanks": ["mango"], "text": "It also induces flowering in mango."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s220", "tokens": [{"t": "text", "v": "Since ethylene regulates so many physiological processes, it is one of the most widely used PGR in agriculture."}], "blanks": [], "text": "Since ethylene regulates so many physiological processes, it is one of the most widely used PGR in agriculture."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s221", "tokens": [{"t": "text", "v": "The most widely used compound as source of ethylene is "}, {"t": "cloze", "v": "ethephon"}, {"t": "text", "v": "."}], "blanks": ["ethephon"], "text": "The most widely used compound as source of ethylene is ethephon."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s222", "tokens": [{"t": "text", "v": "Ethephon in an aqueous solution is readily absorbed and transported within the plant and releases ethylene slowly."}], "blanks": [], "text": "Ethephon in an aqueous solution is readily absorbed and transported within the plant and releases ethylene slowly."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s223", "tokens": [{"t": "cloze", "v": "Ethephon"}, {"t": "text", "v": " hastens fruit ripening in "}, {"t": "cloze", "v": "tomatoes and apples"}, {"t": "text", "v": " and accelerates abscission in flowers and fruits (thinning of cotton, cherry, walnut)."}], "blanks": ["Ethephon", "tomatoes and apples"], "text": "Ethephon hastens fruit ripening in tomatoes and apples and accelerates abscission in flowers and fruits (thinning of cotton, cherry, walnut)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s224", "tokens": [{"t": "text", "v": "It promotes "}, {"t": "cloze", "v": "female flowers"}, {"t": "text", "v": " in "}, {"t": "cloze", "v": "cucumbers"}, {"t": "text", "v": " thereby increasing the yield."}], "blanks": ["female flowers", "cucumbers"], "text": "It promotes female flowers in cucumbers thereby increasing the yield."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s225", "tokens": [{"t": "text", "v": "15.4.3.5 "}, {"t": "cloze", "v": "Abscisic acid"}], "blanks": ["Abscisic acid"], "text": "15.4.3.5 Abscisic acid"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s226", "tokens": [{"t": "text", "v": "As mentioned earlier, "}, {"t": "cloze", "v": "abscisic acid (ABA)"}, {"t": "text", "v": " was discovered for its role in regulating "}, {"t": "cloze", "v": "abscission and dormancy"}, {"t": "text", "v": "."}], "blanks": ["abscisic acid (ABA)", "abscission and dormancy"], "text": "As mentioned earlier, abscisic acid (ABA) was discovered for its role in regulating abscission and dormancy."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s227", "tokens": [{"t": "text", "v": "But like other PGRs, it also has other wide ranging effects on plant growth and development."}], "blanks": [], "text": "But like other PGRs, it also has other wide ranging effects on plant growth and development."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s228", "tokens": [{"t": "text", "v": "It acts as a general plant "}, {"t": "cloze", "v": "growth inhibitor"}, {"t": "text", "v": " and an inhibitor of plant metabolism."}], "blanks": ["growth inhibitor"], "text": "It acts as a general plant growth inhibitor and an inhibitor of plant metabolism."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s229", "tokens": [{"t": "text", "v": "ABA inhibits "}, {"t": "cloze", "v": "seed germination"}, {"t": "text", "v": "."}], "blanks": ["seed germination"], "text": "ABA inhibits seed germination."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s230", "tokens": [{"t": "text", "v": "ABA stimulates the "}, {"t": "cloze", "v": "closure of stomata"}, {"t": "text", "v": " and increases the tolerance of plants to various kinds of stresses."}], "blanks": ["closure of stomata"], "text": "ABA stimulates the closure of stomata and increases the tolerance of plants to various kinds of stresses."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s231", "tokens": [{"t": "text", "v": "Therefore, it is also called the "}, {"t": "cloze", "v": "stress hormone"}, {"t": "text", "v": "."}], "blanks": ["stress hormone"], "text": "Therefore, it is also called the stress hormone."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s232", "tokens": [{"t": "text", "v": "ABA plays an important role in seed development, maturation and "}, {"t": "cloze", "v": "dormancy"}, {"t": "text", "v": "."}], "blanks": ["dormancy"], "text": "ABA plays an important role in seed development, maturation and dormancy."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s233", "tokens": [{"t": "text", "v": "By inducing dormancy, ABA helps seeds to withstand "}, {"t": "cloze", "v": "desiccation"}, {"t": "text", "v": " and other factors unfavourable for growth."}], "blanks": ["desiccation"], "text": "By inducing dormancy, ABA helps seeds to withstand desiccation and other factors unfavourable for growth."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s234", "tokens": [{"t": "text", "v": "In most situations, ABA acts as an "}, {"t": "cloze", "v": "antagonist to GAs"}, {"t": "text", "v": "."}], "blanks": ["antagonist to GAs"], "text": "In most situations, ABA acts as an antagonist to GAs."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s235", "tokens": [{"t": "text", "v": "We may summarise that for any and every phase of growth, differentiation and development of plants, one or the other PGR has some role to play."}], "blanks": [], "text": "We may summarise that for any and every phase of growth, differentiation and development of plants, one or the other PGR has some role to play."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s236", "tokens": [{"t": "text", "v": "Such roles could be complimentary or antagonistic. These could be individualistic or synergistic."}], "blanks": [], "text": "Such roles could be complimentary or antagonistic. These could be individualistic or synergistic."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s237", "tokens": [{"t": "text", "v": "Similarly, there are a number of events in the life of a plant where more than one PGR interact to affect that event, e.g., dormancy in seeds/buds, abscission, senescence, "}, {"t": "cloze", "v": "apical dominance"}, {"t": "text", "v": ", etc."}], "blanks": ["apical dominance"], "text": "Similarly, there are a number of events in the life of a plant where more than one PGR interact to affect that event, e.g., dormancy in seeds/buds, abscission, senescence, apical dominance, etc."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s238", "tokens": [{"t": "text", "v": "Remember, the role of PGR is of only one kind of intrinsic control."}], "blanks": [], "text": "Remember, the role of PGR is of only one kind of intrinsic control."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s239", "tokens": [{"t": "text", "v": "Along with "}, {"t": "cloze", "v": "genomic control"}, {"t": "text", "v": " and extrinsic factors, they play an important role in plant growth and development."}], "blanks": ["genomic control"], "text": "Along with genomic control and extrinsic factors, they play an important role in plant growth and development."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s240", "tokens": [{"t": "text", "v": "Many of the extrinsic factors such as temperature and light, control plant growth and development via PGR."}], "blanks": [], "text": "Many of the extrinsic factors such as temperature and light, control plant growth and development via PGR."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s241", "tokens": [{"t": "text", "v": "Some of such events could be: "}, {"t": "cloze", "v": "vernalisation"}, {"t": "text", "v": ", flowering, dormancy, seed germination, plant movements, etc."}], "blanks": ["vernalisation"], "text": "Some of such events could be: vernalisation, flowering, dormancy, seed germination, plant movements, etc."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s242", "tokens": [{"t": "text", "v": "We shall discuss briefly the role of light and temperature (both of them, the extrinsic factors) on initiation of flowering."}], "blanks": [], "text": "We shall discuss briefly the role of light and temperature (both of them, the extrinsic factors) on initiation of flowering."}, {"type": "h4", "content": "15.5 Photoperiodism"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s243", "tokens": [{"t": "text", "v": "It has been observed that some plants require a periodic exposure to light to induce flowering."}], "blanks": [], "text": "It has been observed that some plants require a periodic exposure to light to induce flowering."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s244", "tokens": [{"t": "text", "v": "It is also seen that such plants are able to measure the duration of exposure to light."}], "blanks": [], "text": "It is also seen that such plants are able to measure the duration of exposure to light."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s245", "tokens": [{"t": "text", "v": "For example, some plants require the exposure to light for a period exceeding a well defined critical duration, while others must be exposed to light for a period less than this critical duration before the flowering is initiated in them."}], "blanks": [], "text": "For example, some plants require the exposure to light for a period exceeding a well defined critical duration, while others must be exposed to light for a period less than this critical duration before the flowering is initiated in them."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s246", "tokens": [{"t": "text", "v": "The former group of plants are called "}, {"t": "cloze", "v": "long day plants"}, {"t": "text", "v": " while the latter ones are termed "}, {"t": "cloze", "v": "short day plants"}, {"t": "text", "v": " ."}], "blanks": ["long day plants", "short day plants"], "text": "The former group of plants are called long day plants while the latter ones are termed short day plants ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s247", "tokens": [{"t": "text", "v": "The critical duration is different for different plants."}], "blanks": [], "text": "The critical duration is different for different plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s248", "tokens": [{"t": "text", "v": "There are many plants, however, where there is no such correlation between exposure to light duration and induction of flowering response; such plants are called "}, {"t": "cloze", "v": "day-neutral plants"}, {"t": "text", "v": " (Figure 15.12)."}], "blanks": ["day-neutral plants"], "text": "There are many plants, however, where there is no such correlation between exposure to light duration and induction of flowering response; such plants are called day-neutral plants (Figure 15.12)."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s249", "tokens": [{"t": "text", "v": "It is now also known that not only the duration of light period but that the duration of dark period is also of equal importance."}], "blanks": [], "text": "It is now also known that not only the duration of light period but that the duration of dark period is also of equal importance."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s250", "tokens": [{"t": "text", "v": "Hence, it can be said that flowering in certain plants depends not only on a combination of light and dark exposures but also their relative durations."}], "blanks": [], "text": "Hence, it can be said that flowering in certain plants depends not only on a combination of light and dark exposures but also their relative durations."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s251", "tokens": [{"t": "text", "v": "This response of plants to periods of day/night is termed "}, {"t": "cloze", "v": "photoperiodism"}, {"t": "text", "v": " ."}], "blanks": ["photoperiodism"], "text": "This response of plants to periods of day/night is termed photoperiodism ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s252", "tokens": [{"t": "text", "v": "It is also interesting to note that while shoot apices modify themselves into flowering apices prior to flowering, they (i.e., shoot apices of plants) by themselves cannot percieve photoperiods."}], "blanks": [], "text": "It is also interesting to note that while shoot apices modify themselves into flowering apices prior to flowering, they (i.e., shoot apices of plants) by themselves cannot percieve photoperiods."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s253", "tokens": [{"t": "text", "v": "The site of perception of light/dark duration are the "}, {"t": "cloze", "v": "leaves"}, {"t": "text", "v": "."}], "blanks": ["leaves"], "text": "The site of perception of light/dark duration are the leaves."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s254", "tokens": [{"t": "text", "v": "It has been hypothesised that there is a hormonal substance(s) that is responsible for flowering."}], "blanks": [], "text": "It has been hypothesised that there is a hormonal substance(s) that is responsible for flowering."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s255", "tokens": [{"t": "text", "v": "This hormonal substance migrates from "}, {"t": "cloze", "v": "leaves"}, {"t": "text", "v": " to "}, {"t": "cloze", "v": "shoot apices"}, {"t": "text", "v": " for inducing flowering only when the plants are exposed to the necessary inductive photoperiod."}], "blanks": ["leaves", "shoot apices"], "text": "This hormonal substance migrates from leaves to shoot apices for inducing flowering only when the plants are exposed to the necessary inductive photoperiod."}, {"type": "h4", "content": "15.6 Vernalisation"}, {"type": "sentence", "id": "Plant_Growth_and_Development_s256", "tokens": [{"t": "text", "v": "There are plants for which flowering is either quantitatively or qualitatively dependent on exposure to "}, {"t": "cloze", "v": "low temperature"}, {"t": "text", "v": "."}], "blanks": ["low temperature"], "text": "There are plants for which flowering is either quantitatively or qualitatively dependent on exposure to low temperature."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s257", "tokens": [{"t": "text", "v": "This phenomenon is termed "}, {"t": "cloze", "v": "vernalisation"}, {"t": "text", "v": " ."}], "blanks": ["vernalisation"], "text": "This phenomenon is termed vernalisation ."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s258", "tokens": [{"t": "text", "v": "It prevents "}, {"t": "cloze", "v": "precocious reproductive development"}, {"t": "text", "v": " late in the growing season, and enables the plant to have sufficient time to reach maturity."}], "blanks": ["precocious reproductive development"], "text": "It prevents precocious reproductive development late in the growing season, and enables the plant to have sufficient time to reach maturity."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s259", "tokens": [{"t": "text", "v": "Vernalisation refers specially to the promotion of flowering by a period of "}, {"t": "cloze", "v": "low temperature"}, {"t": "text", "v": "."}], "blanks": ["low temperature"], "text": "Vernalisation refers specially to the promotion of flowering by a period of low temperature."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s260", "tokens": [{"t": "text", "v": "Some important food plants, "}, {"t": "cloze", "v": "wheat, barley, rye"}, {"t": "text", "v": " have two kinds of varieties: winter and spring varieties."}], "blanks": ["wheat, barley, rye"], "text": "Some important food plants, wheat, barley, rye have two kinds of varieties: winter and spring varieties."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s261", "tokens": [{"t": "text", "v": "The ‘spring’ variety are normally planted in the spring and come to flower and produce grain before the end of the growing season."}], "blanks": [], "text": "The ‘spring’ variety are normally planted in the spring and come to flower and produce grain before the end of the growing season."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s262", "tokens": [{"t": "text", "v": "Winter varieties, however, if planted in spring would normally fail to flower or produce mature grain within a span of a flowering season."}], "blanks": [], "text": "Winter varieties, however, if planted in spring would normally fail to flower or produce mature grain within a span of a flowering season."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s263", "tokens": [{"t": "text", "v": "Hence, they are planted in autumn."}], "blanks": [], "text": "Hence, they are planted in autumn."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s264", "tokens": [{"t": "text", "v": "They germinate, and over winter come out as small seedlings, resume growth in the spring, and are harvested usually around mid-summer."}], "blanks": [], "text": "They germinate, and over winter come out as small seedlings, resume growth in the spring, and are harvested usually around mid-summer."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s265", "tokens": [{"t": "text", "v": "Another example of vernalisation is seen in "}, {"t": "cloze", "v": "biennial plants"}, {"t": "text", "v": "."}], "blanks": ["biennial plants"], "text": "Another example of vernalisation is seen in biennial plants."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s266", "tokens": [{"t": "text", "v": "Biennials are "}, {"t": "cloze", "v": "monocarpic plants"}, {"t": "text", "v": " that normally flower and die in the second season."}], "blanks": ["monocarpic plants"], "text": "Biennials are monocarpic plants that normally flower and die in the second season."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s267", "tokens": [{"t": "cloze", "v": "Sugarbeet, cabbages, carrots"}, {"t": "text", "v": " are some of the common biennials."}], "blanks": ["Sugarbeet, cabbages, carrots"], "text": "Sugarbeet, cabbages, carrots are some of the common biennials."}, {"type": "sentence", "id": "Plant_Growth_and_Development_s268", "tokens": [{"t": "text", "v": "Subjecting the growing of a "}, {"t": "cloze", "v": "biennial plant"}, {"t": "text", "v": " to a cold treatment stimulates a subsequent photoperiodic flowering response."}], "blanks": ["biennial plant"], "text": "Subjecting the growing of a biennial plant to a cold treatment stimulates a subsequent photoperiodic flowering response."}]};
